GAMES.prep={start(){const d=rvLocal();app.innerHTML=`${topbar()}<div class="card" style="border:5px solid #8f6bff"><h2 style="margin:0">👀 تحضير الأسبوع القادم</h2><div style="background:#f3e8ff;border:3px dashed #8f6bff;border-radius:14px;padding:8px 12px;margin:8px 0"><b>هذه دروس لم تدرسيها بعد.</b> اقرئيها مرة واحدة بهدوء لتتعرّفي عليها فقط، ولا تحاولي حفظها كلها. نحفظ فقط ما كُتب «احفظي». والأستاذة ستشرحها لكِ بعد ذلك.</div>${PREP.map(p=>`<div class="card" style="background:#fff"><h3 style="margin:0">${p[0]} ${p[1]}: ${p[2]}</h3><ul style="line-height:2;margin:4px 0">${p[3].map(x=>`<li>${x}</li>`).join('')}</ul><div style="background:#fff3b0;border-radius:12px;padding:4px 10px;font-weight:800">🧠 ${p[4]}</div></div>`).join('')}<div class="center"><button class="btn" id="pdn" style="background:#34c25a">قرأتُها ✓</button></div><div id="pO"></div></div><div class="center" style="margin:10px 0"><button class="btn ghost" id="pBk">رجوع لمراجعتي</button></div>`;bindTop();$('#pBk').onclick=()=>GAMES.review.start();$('#pdn').onclick=()=>{rvSetDone(d,'prep',true);sfx('correct');$('#pO').innerHTML='<div class="card center">أحسنتِ! نجيب الأسبوع القادم وأنتِ جاهزة بإذن الله 🌟</div>'}}};
