GAMES.mental={mode:'mul',start(after){GAMES._mAfter=after||home;const best=LS.get('mbest',{});
 app.innerHTML=`${topbar()}<div class="card center" style="border:5px solid #f2b800"><h2 style="margin:0">⚡ حساب ذهني</h2><p class="muted">١٠ دقائق يوميًا تكفي. السرعة تأتي من التكرار الهادئ.</p>${[['mul','✖️ جدول الضرب'],['div','➗ القسمة'],['add','➕ جمع وطرح سريع'],['skip','🦘 عدّ بالقفزات']].map(m=>`<div style="margin:8px 0"><button class="btn" data-mm="${m[0]}" style="background:#f2b800;color:#222;min-width:220px">${m[1]}</button><div class="muted" style="font-size:.8rem">${best[m[0]]?'أفضل زمن: '+best[m[0]]+' ث':'لم تجرّبيها بعد'}</div></div>`).join('')}<button class="btn ghost" id="mBk">رجوع</button></div>`;
 bindTop();$('#mBk').onclick=GAMES._mAfter;$$('[data-mm]').forEach(b=>b.onclick=()=>GAMES.mental.run(b.dataset.mm))},
run(mode){const N=12,r=n=>Math.floor(Math.random()*n);const mk=()=>{let q,a;if(mode==='mul'){const x=2+r(11),y=2+r(11);q=`${x} × ${y}`;a=x*y}else if(mode==='div'){const x=2+r(11),y=2+r(11);q=`${x*y} ÷ ${x}`;a=y}else if(mode==='add'){const x=10+r(80),y=5+r(40);if(r(2)){q=`${x} + ${y}`;a=x+y}else{q=`${x+y} − ${y}`;a=x}}else{const s=[2,3,4,5,6,7,9][r(7)],k=2+r(5);q=`عدّ بـ ${s}: ${Array.from({length:k},(_,i)=>s*(i+1)).join('، ')}، ؟`;a=s*(k+1)}
  const o=new Set([a]);while(o.size<3){const d=[1,2,3,10,-1,-2,-10][r(7)];const v=a+d;if(v>0)o.add(v)}return {q,a,o:shuf([...o])}};
 let i=0,sc=0;const t0=Date.now();const step=()=>{if(i>=N){const sec=Math.round((Date.now()-t0)/1000);const best=LS.get('mbest',{});if(sc>=N-1&&(!best[mode]||sec<best[mode])){best[mode]=sec;LS.set('mbest',best)}finish('mental','حساب ذهني: '+({mul:'ضرب',div:'قسمة',add:'جمع وطرح',skip:'عدّ بالقفزات'}[mode]),sc,N);return}
  const q=mk();app.innerHTML=`${topbar()}<div class="card center"><div class="muted">سؤال ${i+1} من ${N} · ${Math.round((Date.now()-t0)/1000)} ث</div><div style="font-size:2.4rem;font-weight:800;margin:14px 0;direction:ltr">${q.q}</div>${q.o.map(v=>`<button class="btn" data-v="${v}" style="min-width:90px;margin:4px;font-size:1.4rem;background:#f2b800;color:#222">${v}</button>`).join('')}</div>`;bindTop();
  $$('[data-v]').forEach(b=>b.onclick=()=>{const ok=+b.dataset.v===q.a;if(ok){sc++;sfx('correct')}else{sfx('wrong')}b.style.background=ok?'#34c25a':'#ff5a5a';b.style.color='#fff';$$('[data-v]').forEach(x=>{x.disabled=true;if(+x.dataset.v===q.a)x.style.background='#34c25a'});i++;setTimeout(step,ok?350:1100)})};step()}};

